<template><ContentWrap><el-form ref="queryRef" :model="query" inline><el-form-item label="学习任务" prop="taskId"><el-select v-model="query.taskId" clearable filterable class="!w-240px"><el-option v-for="task in tasks" :key="task.id" :label="task.title" :value="task.id" /></el-select></el-form-item><el-form-item label="员工姓名" prop="staffName"><el-input v-model="query.staffName" clearable /></el-form-item><el-form-item label="状态" prop="status"><el-select v-model="query.status" clearable class="!w-150px"><el-option v-for="s in statuses" :key="s.value" :label="s.label" :value="s.value" /></el-select></el-form-item><el-form-item><el-button @click="load">查询</el-button><el-button @click="reset">重置</el-button><el-button type="primary" @click="importRef.open()">导入记录</el-button><el-button :disabled="!query.taskId" @click="showStats">完成情况</el-button><el-button :disabled="!query.taskId" @click="exportRecords">导出</el-button></el-form-item></el-form></ContentWrap><ContentWrap v-if="stats"><el-row :gutter="12"><el-col v-for="item in statItems" :key="item.label" :span="4"><el-statistic :title="item.label" :value="item.value" /></el-col></el-row></ContentWrap><ContentWrap><el-table v-loading="loading" :data="list" stripe><el-table-column label="学习任务" min-width="160"><template #default="{row}">{{ taskName(row.taskId) }}</template></el-table-column><el-table-column label="员工姓名" prop="staffName" /><el-table-column label="科室" prop="department" /><el-table-column label="状态"><template #default="{row}"><el-tag>{{ label(row.status) }}</el-tag></template></el-table-column><el-table-column label="考试分数" prop="score" /><el-table-column label="签到时间" prop="signTime" width="180" /><el-table-column label="完成时间" prop="completeTime" width="180" /><el-table-column label="操作" width="180"><template #default="{row}"><el-button v-if="row.status===0" link type="primary" @click="sign(row.id)">签到</el-button><el-button v-if="row.importBatchNo" link type="danger" @click="rollback(row.importBatchNo)">撤销批次</el-button></template></el-table-column></el-table><Pagination :total="total" v-model:page="query.pageNo" v-model:limit="query.pageSize" @pagination="load" /></ContentWrap><EducationRecordImportForm ref="importRef" @success="load" /></template>
<script setup lang="ts">
import { EducationRecordApi,type EducationRecord } from '@/api/yideyifeng/education/record';import { EducationTaskApi,type EducationTask } from '@/api/yideyifeng/education/task';import EducationRecordImportForm from './EducationRecordImportForm.vue';import download from '@/utils/download'
const message=useMessage();const statuses=[{value:0,label:'未参加'},{value:1,label:'已参加'},{value:2,label:'已缺席'},{value:3,label:'考试不合格'},{value:4,label:'考试合格'}];const label=(v:number)=>statuses.find(s=>s.value===v)?.label||'未知'
const loading=ref(false),list=ref<EducationRecord[]>([]),tasks=ref<EducationTask[]>([]),total=ref(0),queryRef=ref(),importRef=ref(),stats=ref<any>();const query=reactive({pageNo:1,pageSize:10,taskId:undefined as number|undefined,staffName:undefined,status:undefined});const taskName=(id:number)=>tasks.value.find(item=>item.id===id)?.title||String(id)
const load=async()=>{loading.value=true;try{const data=await EducationRecordApi.getPage(query);list.value=data.list;total.value=data.total}finally{loading.value=false}};const loadTasks=async()=>{const data=await EducationTaskApi.getPage({pageNo:1,pageSize:100});tasks.value=data.list};const reset=()=>{queryRef.value.resetFields();stats.value=undefined;load()};const sign=async(id:number)=>{await EducationRecordApi.sign(id);message.success('签到成功');load()};const rollback=async(batchNo:string)=>{await message.confirm('确认撤销该批次吗？');const count=await EducationRecordApi.rollbackImport(batchNo);message.success(`已撤销 ${count} 条记录`);load()};const showStats=async()=>{stats.value=await EducationRecordApi.getStatistics(Number(query.taskId))};const exportRecords=async()=>download.excel(await EducationRecordApi.exportRecords(Number(query.taskId)),'学习记录.xlsx');const statItems=computed(()=>stats.value?[{label:'应参加',value:stats.value.totalCount},{label:'已完成',value:stats.value.completedCount},{label:'未完成',value:stats.value.incompleteCount},{label:'缺席',value:stats.value.absentCount},{label:'不合格',value:stats.value.failedCount},{label:'完成率(%)',value:stats.value.completionRate}]:[]);onMounted(()=>{load();loadTasks()})
</script>
